import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"发布工程版本","description":"将已核对的开发内容构建为工程版本，查看构建结果，再选择生产部署，并区分恢复开发与回滚运行。","frontmatter":{"title":"发布工程版本","description":"将已核对的开发内容构建为工程版本，查看构建结果，再选择生产部署，并区分恢复开发与回滚运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/project-releases.md","filePath":"zh/使用指南/发布工程版本.md"}'),i={name:"zh/guide/project-releases.md"};function n(s,a,l,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="发布工程版本" tabindex="-1">发布工程版本 <a class="header-anchor" href="#发布工程版本" aria-label="Permalink to &quot;发布工程版本&quot;">​</a></h1><p>工程版本用于固定一份可部署的工程内容。<strong>平台产品的 v1.0 与某个工程的发布版本不是同一编号。</strong></p><p>本页由有该工程发布权限的成员操作。开始前保存源码、查询、计算、报警、身份与历史等本次改动，并完成必要的开发验证；AI 回复“完成”不能替代这些步骤。</p><h2 id="_1-创建下一版本" tabindex="-1">1. 创建下一版本 <a class="header-anchor" href="#_1-创建下一版本" aria-label="Permalink to &quot;1. 创建下一版本&quot;">​</a></h2><ol><li>从“工程管理”找到目标工程，打开 <strong>“发布工程”</strong>。</li><li>核对工程名称及已有版本，点击 <strong>“创建下一版本”</strong>。</li><li>等待构建与版本状态，必要时查看 <strong>“构建日志”</strong>。</li><li>确认版本构建成功、可用于生产部署，再记下实际版本号。</li></ol><p>版本由平台递增，不需要照抄手册的产品 v1.0。创建请求已受理、构建中和构建成功是不同状态，不连续创建多个版本催促。</p><p>出现“版本已创建，列表刷新失败”时，先重新读取已有版本，不立即再点创建。</p><h2 id="_2-核对本次内容" tabindex="-1">2. 核对本次内容 <a class="header-anchor" href="#_2-核对本次内容" aria-label="Permalink to &quot;2. 核对本次内容&quot;">​</a></h2><p>确认这一版包含预期的源码和已保存工程配置。查询、点位、计算、报警、权限和历史都应按各自入口核对，见<a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a>。</p><p>构建成功说明制品已经形成，不代表现场设备、外部接口、通知送达和全部业务都已验证。不要把构建日志中的成功当成运行验收。</p><h2 id="_3-到运维中选择版本" tabindex="-1">3. 到运维中选择版本 <a class="header-anchor" href="#_3-到运维中选择版本" aria-label="Permalink to &quot;3. 到运维中选择版本&quot;">​</a></h2><p>进入 <strong>“运维管理” → “工程部署” → “创建工程部署”</strong>，选择工程、生产模式和本次构建成功的版本，再按<a href="/induframe-docs/zh/guide/deployments.html">部署说明</a>选择环境、节点和访问方式。</p><p>已有部署时，明确确认替换与“更新部署”，随后查看实际运行版本、健康状态和业务结果。新版本创建成功不会自动替换所有运行环境。</p><p><strong>重新部署只重下发当前制品，不自动切换到刚发布的新版本。</strong></p><h2 id="_4-基于此版本继续开发-不是运行回滚" tabindex="-1">4. “基于此版本继续开发”不是运行回滚 <a class="header-anchor" href="#_4-基于此版本继续开发-不是运行回滚" aria-label="Permalink to &quot;4. “基于此版本继续开发”不是运行回滚&quot;">​</a></h2><p>版本列表中的 **“基于此版本继续开发”**会用该版本替换当前工程的源码、场景和数据配置，界面会提示先备份当前开发内容。先保存需要保留的工作并核对影响，再决定是否继续。</p><p>它改变开发起点，不自动切换正在运行的部署；也不是恢复全部业务数据库或服务器的工具。</p><p>需要恢复运行版本时，应按部署安排明确选择目标版本，不把开发恢复、重新部署与版本切换混为一项操作。</p><h2 id="_5-删除与保留" tabindex="-1">5. 删除与保留 <a class="header-anchor" href="#_5-删除与保留" aria-label="Permalink to &quot;5. 删除与保留&quot;">​</a></h2><p>版本被部署或活动任务引用时不能随意删除。引用状态未知先重新读取，不绕过保护；保留业务需要的可追溯版本与独立备份。</p><p>下一步：<a href="/induframe-docs/zh/guide/deployments.html">工程部署</a> · <a href="/induframe-docs/zh/guide/runtime-data-troubleshooting.html">按数据链路排查</a>。</p>',21)])])}const u=e(i,[["render",n]]);export{c as __pageData,u as default};
